import { ChessComError, type ChessComClient } from "@/lib/chess/client";
import { normalizeChessUsername } from "@/lib/chess/username";
import type { CheckResult } from "@/lib/chess/verification/types";

/**
 * Proof of ownership by temporary code.
 *
 * The student puts a one-time code (generated by the database) into a field of their own
 * Chess.com profile that the account owner can edit and the public API returns — the
 * "Location" (preferred) or "Name" field. We read the public profile and look for the code.
 * Only the owner can edit that field, so seeing the code proves control of the account.
 *
 * Security properties:
 *  - the code is chosen server-side, so it cannot be pointed at text already on someone
 *    else's profile;
 *  - nothing here can produce a false "verified": every failure path returns `verified: false`;
 *  - no Chess.com password, cookie or token is ever requested or stored.
 *
 * Caveat (documented for operators): Chess.com serves published data through a cache, so a
 * profile edit can take a while to appear in the API. "code_not_found" therefore means "not
 * visible yet", and the student may retry or fall back to administrator review.
 */
export function profileContainsCode(
  profile: { location?: string; name?: string },
  code: string,
): boolean {
  const needle = code.trim().toUpperCase();
  if (needle.length < 8) return false;
  const haystack = [profile.location, profile.name].filter(Boolean).join("\n").toUpperCase();
  return haystack.includes(needle);
}

export async function checkProfileCode(
  client: Pick<ChessComClient, "getProfile">,
  input: { username: string; code: string },
): Promise<CheckResult> {
  const expected = normalizeChessUsername(input.username);
  try {
    const profile = await client.getProfile(expected);
    if (normalizeChessUsername(profile.username) !== expected) {
      return { verified: false, reason: "username_mismatch" };
    }
    if (profile.status?.toLowerCase().startsWith("closed")) {
      return { verified: false, reason: "account_closed" };
    }
    if (!profileContainsCode(profile, input.code)) {
      return { verified: false, reason: "code_not_found" };
    }
    return { verified: true, username: expected, playerId: profile.player_id ?? null };
  } catch (error) {
    if (error instanceof ChessComError) {
      if (error.kind === "not_found" || error.kind === "gone")
        return { verified: false, reason: "profile_not_found" };
      if (error.kind === "moved") return { verified: false, reason: "renamed" };
      if (error.kind === "rate_limited") return { verified: false, reason: "rate_limited" };
      return { verified: false, reason: "unavailable", detail: error.kind };
    }
    return { verified: false, reason: "unavailable" };
  }
}
